-- 005c_seed_directivos.sql
-- Seed de directivos e historial institución-directivo.
-- Fuente: escuelas_cordoba - seed (2)(1).csv
--
-- Esperado:
--   instituciones:           5,489
--   directivos únicos:       4,572
--   relaciones:              5,489
--
-- Este seed NO crea una restricción UNIQUE sobre directivos.nombre.
-- El mismo nombre puede corresponder a distintas personas.
-- Las fechas desde/hasta quedan NULL porque el CSV no contiene historial.

BEGIN;

-- ============================================================
-- 1. Preflight
-- ============================================================

DO $$
DECLARE
    institution_count INTEGER;
    directivo_count INTEGER;
    relation_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO institution_count FROM institutions;
    SELECT COUNT(*) INTO directivo_count FROM directivos;
    SELECT COUNT(*) INTO relation_count FROM institution_directives;

    IF institution_count <> 5489 THEN
        RAISE EXCEPTION
            'Preflight 005c abortado: se esperaban 5489 instituciones y hay %',
            institution_count;
    END IF;

    IF directivo_count <> 0 THEN
        RAISE EXCEPTION
            'Preflight 005c abortado: directivos no está vacío (% filas)',
            directivo_count;
    END IF;

    IF relation_count <> 0 THEN
        RAISE EXCEPTION
            'Preflight 005c abortado: institution_directives no está vacío (% filas)',
            relation_count;
    END IF;
END $$;

