INSERT INTO institution_directives (
    institution_id,
    directivo_id,
    desde,
    hasta
)
SELECT
    i.id,
    d.id,
    NULL,
    NULL
FROM source_data s
JOIN institutions i
    ON i.cue = s.cue
JOIN directivos d
    ON d.nombre = s.directivo_nombre;

-- ============================================================
-- 4. Validaciones
-- ============================================================

DO $$
DECLARE
    directivo_count INTEGER;
    relation_count INTEGER;
    institutions_without_directivo INTEGER;
    invalid_institution_refs INTEGER;
    invalid_directivo_refs INTEGER;
    duplicate_relations INTEGER;
BEGIN
    SELECT COUNT(*) INTO directivo_count
    FROM directivos;

    IF directivo_count <> 4572 THEN
        RAISE EXCEPTION
            'Validación 005c falló: se esperaban 4572 directivos y hay %',
            directivo_count;
    END IF;

    SELECT COUNT(*) INTO relation_count
    FROM institution_directives;

    IF relation_count <> 5489 THEN
        RAISE EXCEPTION
            'Validación 005c falló: se esperaban 5489 relaciones y hay %',
            relation_count;
    END IF;

    SELECT COUNT(*)
    INTO institutions_without_directivo
    FROM institutions i
    WHERE NOT EXISTS (
        SELECT 1
        FROM institution_directives id
        WHERE id.institution_id = i.id
    );

    IF institutions_without_directivo <> 0 THEN
        RAISE EXCEPTION
            'Validación 005c falló: hay % instituciones sin directivo',
            institutions_without_directivo;
    END IF;

    SELECT COUNT(*)
    INTO invalid_institution_refs
    FROM institution_directives id
    LEFT JOIN institutions i
        ON i.id = id.institution_id
    WHERE i.id IS NULL;

    IF invalid_institution_refs <> 0 THEN
        RAISE EXCEPTION
            'Validación 005c falló: hay % relaciones con institución inválida',
            invalid_institution_refs;
    END IF;

    SELECT COUNT(*)
    INTO invalid_directivo_refs
    FROM institution_directives id
    LEFT JOIN directivos d
        ON d.id = id.directivo_id
    WHERE d.id IS NULL;

    IF invalid_directivo_refs <> 0 THEN
        RAISE EXCEPTION
            'Validación 005c falló: hay % relaciones con directivo inválido',
            invalid_directivo_refs;
    END IF;

    SELECT COUNT(*)
    INTO duplicate_relations
    FROM (
        SELECT institution_id, directivo_id, COUNT(*) AS cantidad
        FROM institution_directives
        GROUP BY institution_id, directivo_id
        HAVING COUNT(*) > 1
    ) duplicates;

    IF duplicate_relations <> 0 THEN
        RAISE EXCEPTION
            'Validación 005c falló: hay % relaciones institución-directivo duplicadas',
            duplicate_relations;
    END IF;

    RAISE NOTICE '005c OK: % directivos, % relaciones, todas las instituciones tienen directivo.',
        directivo_count, relation_count;
END $$;

COMMIT;
